\label{th-misu-intro}
Suppose that there exist $(Y_0,f_0) \in \mathcal Y$ and a saddle point $r(f_0)$ of index $(s,u+1)$, with $s=k-u-1$, such that:
\begin{itemize}
\item[\textbf{(1)}] $T_{f_0}^{\wedge(u+1)}\wedge[W^u_{r(f_0),loc}]\neq 0$;
\item[\textbf{(2)}] there exists $n_0 \geq 0$ such that
\[f_0^{n_0}(Y_0)\cap W^s_{r(f_0),loc}\neq\varnothing;\]
\item[\textbf{(3)}] there exist pairs $(Y,f)\in\mathcal Y$, arbitrarily close to $(Y_0,f_0)$, such that
\[f^{n_0}(Y)\cap W^s_{r(f),loc}=\varnothing.\]
\end{itemize}
Then $(Y_0,f_0)$ belongs to the support of the current $T_{\mathcal Y}$.

\label{prop-dynaslope}
Under conditions \eqref{eq-bun} and \eqref{eq-res}, for each $1\leq i\leq u$, there exists a holomorphic section $\mathcal E_f^{u,i}$ of the bundle $E$, invariant under $f_*$, depending holomorphically on $f$, and satisfying
\[\mathcal E_f^{u,i}(p(f))=e_i^u(f).\]

\label{prop-holomorphic-jets}
Let $1\leq r<\ell$ and assume moreover that, for the constants
$0<a<b<1$ appearing in \eqref{eq-bun},
\begin{equation}\label{eq-higher-bunching}
    b^{\ell-r}<a^{r+1}.
\end{equation}
Let $\theta$ be a $C^\ell$-linearization normalized by $D_{p}\theta=\mathrm{id}.$ Then, the $r$-jet of $\theta$ is holomorphic at every point of
\[
W^s_{p,loc}\cup W^u_{p,loc}.
\]

\label{le-inter}
Let $X$ be a $u$-graph (resp.\ $s$-graph) and $Y$ a $cs$-graph (resp.\ $cu$-graph) in $\mathcal N$.
Then $X\cap Y$ consists of a single point, and the intersection is transverse.

\label{def-hl}
An injective holomorphic map defined on a neighborhood of $\overline{\mathcal N}$
is called a \emph{horizontal-like map of index $(s+1,u)$} from $\mathcal N$
to $\mathcal N'$ if
\begin{itemize}
\item $f(\mathcal N)\cap\mathcal N\neq\varnothing$,
\item $f(\partial_u\mathcal N)\cap\overline{\mathcal N'}=\varnothing$,
\item $f(\overline{\mathcal N})\cap\partial\mathcal N'\subset\partial_u\mathcal N'$.
\end{itemize}

\label{prop-hyp-graphs}
In the situation above, we have that
\begin{itemize}
\item the local stable manifolds $W^s_{x,loc}$, for $x\in\Lambda$, are $s$-graphs in $\tilde{\mathcal N}$,
\item for each $\hat x$ in the natural extension $\hat\Lambda$ of $\Lambda$, the local unstable manifold $W^u_{\hat x,loc}$ is a $cu$-graph in $\mathcal N'$.
\end{itemize}
Moreover, these invariants manifolds are contained in the standard stable and unstable manifolds respectively and they depends holomorphically on $f.$

\label{tm:small-distrib}
Let $\hat{f}:\mathbb{P}^k\times \mathcal{Y}\to \mathbb{P}^k\times\mathcal{Y}$ be a family of endomorphisms of degree $d$ parametrized by a quasiprojective variety $\mathcal{Y}$, and let $\hat{\mathcal{Y}}\subset\mathbb{P}^k\times \mathcal{Y}$ be an irreducible closed proper subvariety, all defined over a number field $\mathbb{K}$. Assume $\mu_{\mathcal{Y}}$ is non-zero. Assume also there is a generic sequence $\{F_i\}_i$ of finite Galois invariant subsets of $\mathcal{Y}(\bar{\mathbb{Q}})$ such that for all $t\in \bigcup_iF_i$, the subvariety $Y_t$ of $\mathbb{P}^k$ is $f_t$-special. Then for any $\varphi\in\mathscr{C}^0_c(\mathcal{Y}(\mathbb{C}),\mathbb{R})$, we have
\[\lim_{i\to\infty}\frac{1}{\# F_i}\sum_{t\in F_i}\varphi(t)=\int_{\mathcal{Y}(\mathbb{C})}\varphi \, \frac{\mu_{\mathcal{Y}}}{\mu_{\mathcal{Y}}(\mathcal{Y}({\mathbb C}))}.\]

\label{le-cond1}
The condition \textup{\ref{it:cond1}} is equivalent to
\begin{enumerate}[label=\textbf{(\arabic*')}]
\item\label{it:cond1'} for each $1\leq j\leq m,$ we have $T_{f_{t_0}}^{\wedge(u+1)}\wedge[W^u_{r_j(f_{t_0}),loc}]\neq 0$.
\end{enumerate}
Furthermore, it implies the condition
\begin{enumerate}[label=\textbf{(\arabic*'')}]
\item\label{it:cond1''} $(T_{f^{[m]}_{t_0}})^{\wedge m(u+1)}\wedge[W^u_{r(f_{t_0}),loc}]\neq 0$.
\end{enumerate}

\label{th-main-blender}
Let
\[
\mathcal{Y}\subset \mathcal{X}_D^u\times \operatorname{End}_d^k
\]
be an irreducible, dynamically full and maximally varying family.
If $(Y,f)\in\mathcal{Y}$ with $f\in\Omega_u$ and $Y$ reduced and irreducible satisfies
\begin{equation}\tag{$\pitchfork$}\label{eq-pitch}
f^n(Y)\text{ intersects }W^s_{p(f),loc}\text{ transversely
for some }n\geq0,
\end{equation}
then $(Y,f)$ belongs to the support of $\mu_{\mathcal Y}$.

\label{rk-irreducible}
Observe that, since the member $Y$ in Theorem~\ref{th-main-blender} is reduced and irreducible, the family $\mathcal Y$ is generically irreducible. Without this assumption, a general member $(Y,f)$ could have a decomposition $Y=\sum_{j=1}^r m_j[Y_j]$, with some components $Y_j$ failing to satisfy \eqref{eq-pitch}.
Variations affecting only these components would then not be detected by our transversality argument, and the measure $\mu_{\mathcal Y}$ could therefore vanish.

\label{rk-control1}
 By taking $h_f\colon (x^c,x^s)\mapsto(x^c,x^s,z)$ for a fixed $z\in B^u,$ we obtain that the graph transform $f^n(\Gamma(f))$ is given by
\[f^n(\Gamma(f))=\left\{\left(\chi_{p(f)}^{n}b^c(f)\Big[\alpha(f)(1,0)+R_{n}(f,z)\Big],z\right)\,;\,z\in B^u\right\}.\]

\label{le-control2}

Let $(\Gamma_l)_{l\geq0}$ be a sequence of families parametrized by $M$ of $u$-graph in $B_r$ intersecting $\mathsf W_{r(f)}^{cs}$ at $(b^c_l(f),b^s_l(f)).$ Assume that this sequence converges to $\Gamma_\infty:=(\Gamma_\infty(f))_{f\in M}$ satisfying
\begin{equation}\label{eq-gammainfty}
\forall f\in M,\ \ \Gamma_\infty(f)\cap W^s_{r(f),loc}\neq\varnothing.
\end{equation}
Then, for each sequence $(n_l)_{l\geq0}$ and for all $f\in M$ such that
\begin{equation}\label{eq-hypcontrol2}
\tilde\chi^{-2n_l}=o(b_l^c(f))\ \text{ and }\ |\chi_{r(f)}^{n_l}b^c_l(f)\beta(f)|<1/4,
\end{equation}
the graph transform $f^{n_l}(\Gamma_l(f))$ is a subset of the form
\begin{equation}\label{eq-controle2}
\left\{\left(\chi_{r(f)}^{n_l}b^c_l(f)\Big[\beta(f)(1,0)+S_{n_l}(f,z)\Big],z\right)\,;\,z\in B^u\right\},
\end{equation}
where the error term $S_{n_l}$ is holomorphic and converges to $0$ locally uniform with respect to $f \in M$ and $z\in B^u$.

\label{le-doublecontrole}
There exists a holomorphic function $\gamma\colon M\to\mathbb{C}^*$  such that if $(j_n)$ and $(l_n)$ are sequences then for all $f\in M$ such that
\begin{equation}\label{eq-hypdoublecontrole}
\tilde\chi^{-2l_n}=o(\chi_{p(f)}^{j_n})\ \text{ and }\ |\Xi_{j_n,l_n}(f)\gamma(f)|\leq 1/4,
\end{equation}
the set $f^{j_n+n_0+l_n}(\Gamma(f))$ contains, for all $n$ large enough, a $u$-graph $\Gamma_{j_n,l_n}(f)$ in $B_{r_0}$ of the form
\begin{equation}\label{eq-doublecontrole}
\Gamma_{j_n,l_n}(f)=\left\{\left(\Xi_{j_n,l_n}(f)\gamma(f)\Big[(1,0)+S_{n}(f,z)\Big],z\right)\,;\,z\in B^u\right\},
\end{equation}
where the remainders $S_{n}(f,z)$ converges to $0$ locally uniformly.

\label{prop-relation}
 There exists $\zeta\in\mathbb{S}^1$ and $\omega\in\mathbb{R}^*_+$ such that for all $f\in M$
\[\chi_{r_0(f)}=\zeta\chi_{p(f)}^{-\omega}.\]

\label{le-triplecontrole}
There exists a holomorphic function $\delta\colon M\to\mathbb{C}^*$  such that, if $(m_n)$ is a sequence then, for all $f\in M$ such that
\begin{equation}\label{eq-hyptriplecontrole}
\tilde\chi^{-2m_n}=o(\Xi_{j_n,l_n}(f)-t_i(f))\ \text{ and }\ \left|\delta(f)\big(\Xi_{j_n,l_n}(f)-t_i(f)\big)\chi_{r_i(f)}^{m_n}\right|\leq 1/4,
\end{equation}
the set $f^{j_n+n_0+l_n+n_i+m_n}(\Gamma(f))$ contains a $u$-graph $\tilde\Gamma_{n}(f)$ in $B_{r_i}$ of the form
\begin{equation}\label{eq-triplecontrole}
\tilde\Gamma_{n}(f)=\left\{\left(\delta(f)\big(\Xi_{j_n,l_n}(f)-t_i(f)\big)\chi_{r_i(f)}^{m_n}\Big[(1,0)+\tilde S_{n}(f,z)\Big],z\right)\,;\,z\in B^u\right\},
\end{equation}
where the remainders $\tilde S_{n}(f,z)$ converges to $0$ locally uniformly.

\label{le-decalage}
Possibly after increasing $\delta$, Assumption~\ref{decalage}
holds at $f_0$.

\label{le-grille-2}
Possibly after increasing $\delta$, Assumption~\ref{grille}
holds at $f_0$.

\label{le-init}
Possibly after shrinking $V_0$, Assumptions~\ref{free} and
\ref{init} hold on $V_0$.

\label{le-delta}
If $C$ is an irreducible component of $\Delta_n$, then for every
$m>n$ it has a nonempty proper intersection with $\Delta_m$ in $\mathbb{C}^2$.
